       "Unclaimed": "with task_list as ( select task.name_, task.proc_def_id_, task.assignee_, task.create_time_, task.id_, hiproinst.start_time_, hiproinst.proc_inst_id_, hiproinst.proc_def_key_, hiproinst.state_ from camunda.act_hi_procinst hiproinst inner join camunda.act_ru_task task on hiproinst.proc_inst_id_ = task.proc_inst_id_ where task.assignee_ is null and hiproinst.tenant_id_ = :tenantidstr and hiproinst.start_time_ between :StartDate AND :EndDate and hiproinst.proc_def_key_ not in ( ''invoice'', ''ReviewInvoice'', ''Orchestrator'', ''Sanctions'' ) limit 10000 ), finalstatus_cte as ( select text_, proc_inst_id_ from camunda.act_hi_varinst where proc_inst_id_ in (select proc_inst_id_ from task_list) and name_ = ''current_final_status'' and var_type_ = ''string'' ), finalselectedtxn_cte as ( select bytearray_id_, proc_inst_id_, text_ from camunda.act_hi_varinst where proc_inst_id_ in (select proc_inst_id_ from task_list) and name_ = ''current_final_selected_txn'' ), finalselectedtxnbytes_cte as ( select id_, finalselectedtxn_cte.proc_inst_id_, bytes_ from finalselectedtxn_cte inner join camunda.act_ge_bytearray on finalselectedtxn_cte.bytearray_id_ = id_ where finalselectedtxn_cte.bytearray_id_ is not null  ), payer_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), payee_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), ticket_id_cte AS ( SELECT proc_inst_id_, long_ FROM camunda.act_hi_varinst WHERE name_ = ''TicketID'' AND var_type_ IN (''long'', ''integer'') AND proc_inst_id_ IN ( SELECT pr