t_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) ) -2 ) END, '', '' ), 1 ) AS \\"Txn Count\\", task.name_ as \\"Stage\\", null as \\"Claimed By\\", task.start_time_ \\"Created Date\\", CASE WHEN task.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Ticket Status\\", workflowmasters.workflowname as \\"Case Type\\", null as \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\", null as \\"Closed Date\\", null as \\"Closed By\\", txnid.text_ as \\"Txn ID\\", hstatus.text_ as \\"Hold Status\\", mername.text_ as \\"Merchant Name\\", tamt.double_ as \\"Total Amount\\", CASE WHEN isBlack.long_ = 1 and SettlementType.text_ = ''HOLD'' THEN ''Auto Hold'' WHEN isBlack.long_ = 0 and SettlementType.text_ = ''HOLD'' THEN ''Manual Hold'' WHEN SettlementType.text_ = ''RELEASE'' THEN ''Release'' ELSE NULL END AS \\"Settlement Request\\", null AS \\"Released Date\\" from task_list task left join finalstatus_cte finalstatus on finalstatus.proc_inst_id_ = task.proc_inst_id_ left join finalselectedtxn_cte finalselectedtxn on finalselectedtxn.proc_inst_id_ = task.proc_inst_id_ left join finalselectedtxnbytes_cte finalselectedtxnbytes on finalselectedtxnbytes.proc_inst_id_ = task.proc_inst_id_ left join ui.workflowmasters workflowmasters on workflowmasters.workflowkey = task.proc_def_key_ and workflowmasters.itenantid = :tenantid left join payer_cte payer on payer.proc_inst_id_ = task.proc_inst_id_ left join payee_cte payee on payee.proc_inst_id_ = task.proc_inst_id_ left join transaction_amount_cte TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ left join ticket_id_cte TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ left join alert_cte Alert on Alert.proc_inst_id_ = task.proc_inst_id_ left join txnid_cte txnid on txnid.proc_inst_id_ = task.proc_inst_id_ left join