eger'') AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), alert_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''Alert'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), txnid_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''transaction_id'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), hstatus_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''settlementStatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), mername_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''merchantName'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), tamt_cte AS ( SELECT proc_inst_id_, double_ FROM camunda.act_hi_varinst WHERE name_ = ''totalAmountHolded'' AND var_type_ = ''double'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), isBlack_cte AS ( SELECT proc_inst_id_, long_ FROM camunda.act_hi_varinst WHERE name_ = ''isBlacklist'' AND var_type_ = ''boolean'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), SettlementType_cte AS ( SELECT proc_inst_id_, text_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY create_time_ DESC ) AS rn FROM camunda.act_hi_varinst WHERE name_ = ''settlementType'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), releaseStatus_cte AS ( SELECT id_, proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''releasestatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list where state_ = ''COMPLETED'' ) ), releaseDetail_cte AS ( SELECT releasestatus.proc_inst_id_, details.time_, releasestatus.text_, ROW_NUMBER() OVER ( PARTITION BY releasestatus.proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM releaseStatus_cte releasestatus left JOIN camunda.act_hi_detail details ON releasestatus.id_ = details.var_inst_id_ WHERE releasestatus.text_ = ''SUCCESS'' ), ranked_oplog AS ( SELECT time_,proc_inst_id_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), ranked_closedby AS ( SELECT proc_inst_id_,assignee_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC ) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list where state_ = ''COMPLETED'' ) ) select finalstatus.text_ as \\"Settlement Action\\", case when finalselectedtxnbytes.id_ is null then finalselectedtxn.text_ else SUBSTRING( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) FROM 2 FOR LENGTH( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) ) -2 ) end as \\"Associated Transaction\\", array_length( string_to_array( CASE WHEN finalselectedtxnbytes.id_ IS NULL THEN finalselectedtxn.text_ ELSE SUBSTRING( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) FROM 2 FOR LENGTH( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) ) -2 ) END, '', '' ), 1 ) AS \\"Txn Count\\", task.name_ as \\"Stage\\", cuser.vcemailid as \\"Claimed By\\", task.start_time_ \\"Created Date\\", CASE WHEN task.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Ticket Status\\", workflowmasters.workflowname as \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\", task.end_time_ as \\"Closed Date\\", CASE WHEN task.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ is not null THEN clsuser.vcemailid ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", txnid.text_ as \\"Txn ID\\",