ar_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), txnid_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''transaction_id'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), hstatus_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''settlementStatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), mername_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''merchantName'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), tamt_cte AS ( SELECT proc_inst_id_, double_ FROM camunda.act_hi_varinst WHERE name_ = ''totalAmountHolded'' AND var_type_ = ''double'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), isBlack_cte AS ( SELECT proc_inst_id_, long_ FROM camunda.act_hi_varinst WHERE name_ = ''isBlacklist'' AND var_type_ = ''boolean'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), SettlementType_cte AS ( SELECT proc_inst_id_, text_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY create_time_ DESC ) AS rn FROM camunda.act_hi_varinst WHERE name_ = ''settlementType'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), releaseStatus_cte AS ( SELECT id_, proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''releasestatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list where state_ = ''COMPLETED'' ) ), releaseDetail_cte AS ( SELECT releasestatus.proc_inst_id_, details.time_, releasestatus.text_, ROW_NUMBER() OVER ( PARTITION BY releasestatus.proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM releaseStatus_cte releasestatus left JOIN camunda.act_hi_detail details ON releasestatus.id_ = details.var_inst_id_ WHERE releasestatus.text_ = ''SUCCESS'' ), ranked_oplog AS ( SELECT time_,proc_inst_id_, ROW_NUMBER() O