ist ) ), alert_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''Alert'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), txnid_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''transaction_id'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), hstatus_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''settlementStatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), mername_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''merchantName'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), tamt_cte AS ( SELECT proc_inst_id_, double_ FROM camunda.act_hi_varinst WHERE name_ = ''totalAmountHolded'' AND var_type_ = ''double'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), isBlack_cte AS ( SELECT proc_inst_id_, long_ FROM camunda.act_hi_varinst WHERE name_ = ''isBlacklist'' AND var_type_ = ''boolean'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), SettlementType_cte AS ( SELECT proc_inst_id_, text_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY create_time_ DESC ) AS rn FROM camunda.act_hi_varinst WHERE name_ = ''settlementType'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), releaseStatus_cte AS ( SELECT id_, proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''releasestatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list where state_ = ''COMPLETED'' ) ), releaseDetail_cte AS ( SELECT releasestatus.proc_inst_id_, details.time_, releasestatus.text_, ROW_NUMBER() OVER ( PARTITION BY releasestatus.proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM releaseStatus_cte releasestatus left JOIN camunda.act_hi_detail details ON releasestatus.id_ = details.var_inst_id_ WHERE releasestatus.text_ = ''SUCCESS'' ), ranked_oplog AS ( SELECT time_,proc_inst_id_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), ranked_closedby AS ( SELECT proc_inst_id_,assignee_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC ) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list where state_ = ''COMPLETED'' ) ) select finalstatus.text_ as \\"Settlement Action\\", case when finalselectedtxnbytes.id_ is null then finalselectedtxn.text_ else SUBSTRING( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) FROM 2 FOR LENGTH( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) ) -2 ) end as \\"Associated Transaction\\", array_length( string_to_array( CASE WHEN finalselectedtxnbytes.id_ IS NULL THEN finalselectedtxn.text_ ELSE SUBSTRING( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) FROM 2 FOR LENGTH( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) ) -2 ) END, '', '' ), 1 ) AS \\"Txn Count\\", task.name_ as \\"Stage\\", cuser.vcemailid as \\"Claimed By\\", task.start_time_ \\"Created Date\\", CASE WHEN task.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Ticket Status\\", workflowmasters.workflowname as \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\", task.end_time_ as \\"Closed Date\\", CASE WHEN task.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ is not null THEN clsuser.vcemailid ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", txnid.text_ as \\"Txn ID\\", hstatus.text_ as \\"Hold Status\\", mername.text_ as \\"Merchant Name\\", tamt.double_ as \\"Total Amount\\", CASE WHEN isBlack.long_ = 1 and SettlementType.text_ = ''HOLD'' THEN ''Auto Hold'' WHEN isBlack.long_ = 0 and SettlementType.text_ = ''HOLD'' THEN ''Manual Hold'' WHEN SettlementType.text_ = ''RELEASE'' THEN ''Release'' ELSE NULL END AS \\"Settlement Request\\", CASE WHEN releaseDetail.text_ = ''SUCCESS'' THEN releaseDetail.time_ ELSE NULL END AS \\"Released Date\\" from task_list task left join finalstatus_cte finalstatus on finalstatus.proc_inst_id_ = task.proc_inst_id_ left join finalselectedtxn_cte finalselectedtxn on finalselectedtxn.proc_inst_id_ = task.proc_inst_id_ left join finalselectedtxnbytes_cte finalselectedtxnbytes on finalselectedtxnbytes.proc_inst_id_ = task.proc_inst_id_ left JOIN ui.webuser cuser ON cast(task.assignee_ as integer) = cuser.iuserid left join ui.workflowmasters workflowmasters on workflowmasters.workflowkey = task.proc_def_key_ and workflowmasters.itenantid = :tenantid left join payer_cte payer on payer.proc_inst_id_ = task.proc_inst_id_ left join payee_cte payee on payee.proc_inst_id_ = task.proc_inst_id_ left join transaction_amount_cte TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ left join ticket_id_cte TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ left join alert_cte Alert on Alert.proc_inst_id_ = task.proc_inst_id_ left join txnid_cte txnid on txnid.proc_inst_id_ = task.proc_inst_id_ left join hstatus_cte hstatus on hstatus.proc_inst_id_ = task.proc_inst_id_ left join mername_cte mername on mername.proc_inst_id_ = task.proc_inst_id_ left join tamt_cte tamt on tamt.proc_inst_id_ = task.proc_inst_id_ left join isBlack_cte isBlack on isBlack.proc_inst_id_ = task.proc_inst_id_ left join SettlementType_cte SettlementType on SettlementType.proc_inst_id_ = task.proc_inst_id_ and SettlementType.rn = 1 left join ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 left join ranked_closedby closedby ON closedby.proc_inst_id_ = task.proc_inst_id_ AND closedby.rn = 1 left join ui.webuser clsuser ON cast(closedby.assignee_ as integer) = clsuser.iuserid left join releaseDetail_cte releaseDetail ON releaseDetail.proc_inst_id_ = task.proc_inst_id_ and releaseDetail.rn = 1",
       "Closed": "with task_list as ( select hiproinst.start_time_, hiproinst.proc_inst_id_, hiproinst.proc_def_key_, hiproinst.state_, hiproinst.end_time_ from camunda.act_hi_procinst hiproinst where hiproinst.state_ = ''COMPLETED'' and hiproinst.tenant_id_ = :tenantidstr and hiproinst.start_time_ between :StartDate AND :EndDate and hiproinst.proc_def_key_ = :CaseType limit 10000 ), finalstatus_cte as ( select text_, proc_inst_id_ from camunda.act_hi_varinst where proc_inst_id_ in (select proc_inst_id_ from task_list) and name_ = ''current_final_status'' and var_type_ = ''string'' ), finalselectedtxn_cte as ( select bytearray_id_, proc_inst_id_, text_ from camunda.act_hi_varinst where proc_inst_id_ in (select proc_inst_id_ from task_list) and name_ = ''current_final_selected_txn'' ), finalselectedtxnbytes_cte as ( select id_, finalselectedtxn_cte.proc_inst_id_, bytes_ from finalselectedtxn_cte inner join camunda.act_ge_bytearray on finalselectedtxn_cte.bytearray_id_ = id_ where finalselectedtxn_cte.bytearray_id_ is not null  ), payer_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), payee_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), ticket_id_cte AS ( SELECT proc_inst_id_, long_ FROM camunda.act_hi_varinst WHERE name_ = ''TicketID'' AND var_type_ IN (''long'', ''integer'') AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), alert_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''Alert'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), txnid_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''transaction_id'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), hstatus_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''settlementStatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), mername_cte AS ( SELECT proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''merchantName'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), tamt_cte AS ( SELECT proc_inst_id_, double_ FROM camunda.act_hi_varinst WHERE name_ = ''totalAmountHolded'' AND var_type_ = ''double'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), isBlack_cte AS ( SELECT proc_inst_id_, long_ FROM camunda.act_hi_varinst WHERE name_ = ''isBlacklist'' AND var_type_ = ''boolean'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), SettlementType_cte AS ( SELECT proc_inst_id_, text_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY create_time_ DESC ) AS rn FROM camunda.act_hi_varinst WHERE name_ = ''settlementType'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), releaseStatus_cte AS ( SELECT id_, proc_inst_id_, text_ FROM camunda.act_hi_varinst WHERE name_ = ''releasestatus'' AND var_type_ = ''string'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list where state_ = ''COMPLETED'' ) ), releaseDetail_cte AS ( SELECT releasestatus.proc_inst_id_, details.time_, releasestatus.text_, ROW_NUMBER() OVER ( PARTITION BY releasestatus.proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM releaseStatus_cte releasestatus left JOIN camunda.act_hi_detail details ON releasestatus.id_ = details.var_inst_id_ WHERE releasestatus.text_ = ''SUCCESS'' ), ranked_oplog AS ( SELECT time_,proc_inst_id_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY time_ DESC ) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list ) ), ranked_closedby AS ( SELECT proc_inst_id_,assignee_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC ) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT proc_inst_id_ FROM task_list where state_ = ''COMPLETED'' ) ) select finalstatus.text_ as \\"Settlement Action\\", case when finalselectedtxnbytes.id_ is null then finalselectedtxn.text_ else SUBSTRING( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) FROM 2 FOR LENGTH( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) ) -2 ) end as \\"Associated Transaction\\", array_length( string_to_array( CASE WHEN finalselectedtxnbytes.id_ IS NULL THEN finalselectedtxn.text_ ELSE SUBSTRING( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) FROM 2 FOR LENGTH( convert_from( finalselectedtxnbytes.bytes_, ''UTF8'' ) ) -2 ) END, '', '' ), 1 ) AS \\"Txn Count\\", null as \\"Stage\\", null as \\"Claimed By\\", task.start_time_ \\"Created Date\\", ''Closed'' as \\"Ticket Status\\", workflowmasters.workflowname as \\"Case Type\\", null AS \\"Claimed On\\", payer.text_ as \\"Payer\\", payee.text_ as \\"Payee\\", TransactionAmount.double_ / 100 as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\", task.end_time_ as \\"Closed Date\\", CASE WHEN task.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ is not null THEN clsuser.vcemailid ELSE ''Auto Closed'' END ELSE null END as \\"Closed By\\", txnid.text_ as \\"Txn ID\\", hstatus.text_ as \\"Hold Status\\", mername.text_ as \\"Merchant Name\\", tamt.double_ as \\"Total Amount\\", CASE WHEN isBlack.long_ = 1 and SettlementType.text_ = ''HOLD'' THEN ''Auto Hold'' WHEN isBlack.long_ = 0 and SettlementType.text_ = ''HOLD'' THEN ''Manual Hold'' WHEN SettlementType.text_ = ''RELEASE'' THEN ''Release'' ELSE NULL END AS \\"Settlement Request\\", CASE WHEN releaseDetail.text_ = ''SUCCESS'' THEN releaseDetail.time_ ELSE NULL END AS \\"Released Date\\" from task_list task left join finalstatus_cte finalstatus on finalstatus.proc_inst_id_ = task.proc_inst_id_ left join finalselectedtxn_cte finalselectedtxn on finalselectedtxn.proc_inst_id_ = task.proc_inst_id_ left join finalselectedtxnbytes_cte finalselectedtxnbytes on finalselectedtxnbytes.proc_inst_id_ = task.proc_inst_id_ left join ui.workflowmasters workflowmasters on workflowmasters.workflowkey = task.proc_def_key_ and workflowmasters.itenantid = :tenantid left join payer_cte payer on payer.proc_inst_id_ = task.proc_inst_id_ left join payee_cte payee on payee.proc_inst_id_ = task.proc_inst_id_ left join transaction_amount_cte TransactionAmount on TransactionAmount.proc_inst_id_ = task.proc_inst_id_ left join ticket_id_cte TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ left join alert_cte Alert on Alert.proc_inst_id_ = task.proc_inst_id_ left join txnid_cte txnid on txnid.proc_inst_id_ = task.proc_inst_id_ left join hstatus_cte hstatus on hstatus.proc_inst_id_ = task.proc_inst_id_ left join mername_cte mername on mername.proc_inst_id_ = task.proc_inst_id_ left join tamt_cte tamt on tamt.proc_inst_id_ = task.proc_inst_id_ left join isBlack_cte isBlack on isBlack.proc_inst_id_ = task.proc_inst_id_ left join SettlementType_cte SettlementType on SettlementType.proc_inst_id_ = task.proc_inst_id_ and SettlementType.rn = 1 left join ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 left join ranked_closedby closedby ON closedby.proc_inst_id_ = task.proc_inst_id_ AND closedby.rn = 1 left join ui.webuser clsuser ON cast(closedby.assignee_ as integer) = clsuser.iuserid left join releaseDetail_cte releaseDetail ON releaseDetail.proc_inst_id_ = task.proc_inst_id_ and releaseDetail.rn = 1"
